-- Billing infrastructure schema. No payment provider is active until separately configured and verified.
CREATE TABLE IF NOT EXISTS billing_payment_providers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'not_configured' CHECK (status IN ('not_configured','testing','active','suspended')), supported_currencies TEXT[] NOT NULL DEFAULT '{}', credentials_ref TEXT, webhook_secret_ref TEXT, last_tested_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID, email TEXT NOT NULL, billing_name TEXT NOT NULL, billing_country TEXT, tax_identifier TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), order_reference TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES billing_customers(id), organization_id UUID, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','cancelled','refunded')), currency TEXT NOT NULL, amount_minor BIGINT NOT NULL CHECK (amount_minor >= 0), provider_key TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_reference TEXT NOT NULL UNIQUE, order_id UUID REFERENCES billing_orders(id), provider_key TEXT, provider_transaction_reference TEXT, status TEXT NOT NULL CHECK (status IN ('initiated','pending','processing','successful','failed','cancelled','refunded')), currency TEXT NOT NULL, amount_minor BIGINT NOT NULL CHECK (amount_minor >= 0), payment_method_type TEXT, idempotency_key TEXT UNIQUE, verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_number TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES billing_customers(id), organization_id UUID, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','issued','pending','partially_paid','paid','overdue','cancelled','refunded')), currency TEXT NOT NULL, subtotal_minor BIGINT NOT NULL DEFAULT 0, tax_minor BIGINT NOT NULL DEFAULT 0, total_minor BIGINT NOT NULL DEFAULT 0, due_date DATE, payment_reference TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_invoice_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES billing_invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity NUMERIC(18,6) NOT NULL DEFAULT 1, unit_price_minor BIGINT NOT NULL DEFAULT 0, tax_minor BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS billing_subscription_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), plan_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, billing_interval TEXT NOT NULL CHECK (billing_interval IN ('monthly','quarterly','annually','custom')), price_minor BIGINT, currency TEXT, features JSONB NOT NULL DEFAULT '[]', usage_limits JSONB NOT NULL DEFAULT '{}', trial_days INTEGER, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','active','archived')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID REFERENCES billing_customers(id), organization_id UUID, plan_id UUID NOT NULL REFERENCES billing_subscription_plans(id), provider_key TEXT, provider_subscription_reference TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','past_due','paused','cancelled','expired')), current_period_start TIMESTAMPTZ, current_period_end TIMESTAMPTZ, cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_payment_methods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID NOT NULL REFERENCES billing_customers(id), provider_key TEXT NOT NULL, provider_method_reference TEXT NOT NULL, method_type TEXT NOT NULL, brand TEXT, last4 TEXT, exp_month INTEGER, exp_year INTEGER, is_default BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_refund_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES billing_transactions(id), organization_id UUID, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','under_review','approved','rejected','processing','completed')), provider_refund_reference TEXT, reviewed_by TEXT, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_webhook_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider_key TEXT NOT NULL, event_reference TEXT NOT NULL, event_type TEXT NOT NULL, signature_verified BOOLEAN NOT NULL DEFAULT FALSE, idempotency_key TEXT NOT NULL UNIQUE, payload_hash TEXT NOT NULL, processed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS billing_audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_id TEXT, actor_role TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS billing_transactions_status_created_idx ON billing_transactions(status, created_at DESC);
CREATE INDEX IF NOT EXISTS billing_invoices_org_status_idx ON billing_invoices(organization_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS billing_audit_entity_idx ON billing_audit_logs(entity_type, entity_id, created_at DESC);
ALTER TABLE billing_payment_providers ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_customers ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_orders ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_transactions ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_invoices ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_subscriptions ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_payment_methods ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_refund_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_webhook_events ENABLE ROW LEVEL SECURITY; ALTER TABLE billing_audit_logs ENABLE ROW LEVEL SECURITY;
-- No public policies. Gateway webhooks and admin operations require authenticated server-side authorization.
